insert into site.projects (id, slug, name, city, district, address, summary, description, status, completion_date, price_per_m2_usd, cover_image, sort_order, published) values ('00000000-0000-4000-8000-00000000009d', 'gldanula-residence', '{"ka":"გლდანულას რეზიდენცია","en":"Gldanula Residence","ru":"Резиденция Глданула"}'::jsonb, '{"ka":"თბილისი","en":"Tbilisi","ru":"Тбилиси"}'::jsonb, '{"ka":"გლდანულა","en":"Gldanula","ru":"Глданула"}'::jsonb, '{}'::jsonb, '{"ka":"11-სართულიანი საცხოვრებელი კორპუსი, გლდანულა.","en":"A 11-storey residential building in Gldanula.","ru":"11-этажный жилой дом, Глданула."}'::jsonb, '{"ka":"სადემონსტრაციო ტექსტი. ბინები, ფასები და გამოსახულებები შემთხვევითია და ცვლის რეალურ მონაცემებს, სანამ ისინი დაემატება.","en":"Demo text. Flats, prices and images are placeholders until the real data is added.","ru":"Демонстрационный текст. Квартиры, цены и изображения временные, до добавления реальных данных."}'::jsonb, 'under_construction', '2028-06-30', 760, '/demo/gldanula-residence-front.svg', 3, true);
